printChar MACRO char
    mov AH,02h
    mov DL,char
    int 21h
ENDM

.MODEL small
.STACK
.DATA
    COND db 10d
    COND2 db 10B
.CODE
    ;description
    main PROC
        mov DX,@data
        mov DS,DX
        xor DX,DX

        cmp COND,10d
        jne P1

        cmp COND2,10d
        jne P2

        P1:
            printChar 'a'
            jmp P3

        P2:
            printChar 'b'
            jmp P1
        P3:

        .EXIT
    main ENDP

end main